import { useState } from "react";

export default function Counter() {
  const [count, setCount] = useState(0);

  return (
    <div>
      <span>{count}</span>
      <button type="button" onClick={() => setCount((c) => c + 1)}>
        Increment
      </button>
    </div>
  );
}

import { useEffect, useState } from "react";

export default function FetchUsers() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const controller = new AbortController();

    fetch("https://jsonplaceholder.typicode.com/users", { signal: controller.signal })
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then(setUsers)
      .catch((err) => {
        if (err.name !== "AbortError") setError(err);
      })
      .finally(() => {
        if (!controller.signal.aborted) setLoading(false);
      });

    return () => controller.abort();
  }, []);

  if (loading) return <p>Loading…</p>;
  if (error) return <p>Error: {error.message}</p>;

  return (
    <ul>
      {users.map((user) => (
        <li key={user.id}>{user.name}</li>
      ))}
    </ul>
  );
}

import { useMemo, useState } from "react";

const columns = [
  { key: "name", label: "Name" },
  { key: "price", label: "Price" },
  { key: "qty", label: "Qty" },
];

export default function FilterTable({ rows = [] }) {
  const [query, setQuery] = useState("");
  const [sort, setSort] = useState({ key: null, dir: 1 });

  const visible = useMemo(() => {
    const q = query.toLowerCase();
    const filtered = rows.filter((row) => row.name.toLowerCase().includes(q));
    if (!sort.key) return filtered;
    return filtered.toSorted((a, b) => {
      const x = a[sort.key];
      const y = b[sort.key];
      const cmp = typeof x === "string" ? x.localeCompare(y) : x - y;
      return cmp * sort.dir;
    });
  }, [rows, query, sort]);

  const total = visible.reduce((sum, row) => sum + row.price * row.qty, 0);

  function toggleSort(key) {
    setSort((prev) => ({ key, dir: prev.key === key ? -prev.dir : 1 }));
  }

  return (
    <div>
      <input
        type="search"
        placeholder="Search"
        value={query}
        onChange={(e) => setQuery(e.target.value)}
      />
      <table>
        <thead>
          <tr>
            {columns.map((col) => (
              <th key={col.key} onClick={() => toggleSort(col.key)}>
                {col.label}
                {sort.key === col.key && (sort.dir === 1 ? " ▲" : " ▼")}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {visible.map((row, i) => (
            <tr key={`${row.name}-${i}`}>
              <td>{row.name}</td>
              <td>{row.price}</td>
              <td>{row.qty}</td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <td colSpan={2}>Total</td>
            <td>{total}</td>
          </tr>
        </tfoot>
      </table>
    </div>
  );
}

export default function Hello({ name }) {
  return <p>Hello, {name}!</p>;
}

import { useCallback, useEffect, useState } from "react";

export default function KvBrowser({ baseUrl }) {
  const [keys, setKeys] = useState([]);
  const [selected, setSelected] = useState(null);
  const [value, setValue] = useState("");
  const [newKey, setNewKey] = useState("");
  const [newValue, setNewValue] = useState("");
  const [error, setError] = useState(null);

  const request = useCallback(
    async (path, options) => {
      const res = await fetch(`${baseUrl}${path}`, options);
      if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
      return res;
    },
    [baseUrl],
  );

  const run = useCallback(async (action) => {
    try {
      setError(null);
      await action();
    } catch (err) {
      setError(err.message);
    }
  }, []);

  const loadKeys = useCallback(async () => {
    const res = await request("/kv");
    setKeys(await res.json());
  }, [request]);

  useEffect(() => {
    run(loadKeys);
  }, [run, loadKeys]);

  function showValue(key) {
    run(async () => {
      const res = await request(`/kv/${encodeURIComponent(key)}`);
      setValue(await res.text());
      setSelected(key);
    });
  }

  function handleSave(event) {
    event.preventDefault();
    if (!newKey) return;
    run(async () => {
      await request(`/kv/${encodeURIComponent(newKey)}`, { method: "PUT", body: newValue });
      if (selected === newKey) setValue(newValue);
      setNewKey("");
      setNewValue("");
      await loadKeys();
    });
  }

  function handleDelete(key) {
    run(async () => {
      await request(`/kv/${encodeURIComponent(key)}`, { method: "DELETE" });
      if (selected === key) {
        setSelected(null);
        setValue("");
      }
      await loadKeys();
    });
  }

  return (
    <div>
      {error && <p role="alert">Error: {error}</p>}
      <form onSubmit={handleSave}>
        <input placeholder="Key" value={newKey} onChange={(e) => setNewKey(e.target.value)} />
        <input placeholder="Value" value={newValue} onChange={(e) => setNewValue(e.target.value)} />
        <button type="submit">Save</button>
      </form>
      <ul>
        {keys.map((key) => (
          <li key={key}>
            <button type="button" onClick={() => showValue(key)}>
              {key}
            </button>
            <button type="button" onClick={() => handleDelete(key)}>
              Delete
            </button>
          </li>
        ))}
      </ul>
      {selected !== null && (
        <div>
          <h3>{selected}</h3>
          <pre>{value}</pre>
        </div>
      )}
    </div>
  );
}

import { useState } from "react";

export default function Todo() {
  const [items, setItems] = useState([]);
  const [text, setText] = useState("");

  function handleSubmit(event) {
    event.preventDefault();
    const value = text.trim();
    if (!value) return;
    setItems((prev) => [...prev, { id: crypto.randomUUID(), text: value }]);
    setText("");
  }

  function remove(id) {
    setItems((prev) => prev.filter((item) => item.id !== id));
  }

  return (
    <div>
      <form onSubmit={handleSubmit}>
        <input value={text} onChange={(e) => setText(e.target.value)} />
        <button type="submit">Add</button>
      </form>
      <ul>
        {items.map((item) => (
          <li key={item.id}>
            {item.text}
            <button type="button" onClick={() => remove(item.id)}>
              Remove
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
